    attribute alarmLocked : Boolean := false;
    attribute prevD2Pressed : Boolean := false;
    attribute prevD3Pressed : Boolean := false;
    perform action tick {
      first start;
      then if ((io_1) and ((not prevD3Pressed))) {
        first start;
        then assign alarmLocked := false;
        then assign count := 0;
      }
      then if (not alarmLocked) {
        first start;
        then if ((io_0) and ((not prevD2Pressed))) {
          first start;
          then assign count := (if ((count) == (15)) ? 0 else count + 1);
        }
      }
      then if ((((count) == (15))) and ((not alarmLocked))) {
        first start;
        then assign alarmLocked := true;
      }
      then if ((io_1) and ((not prevD3Pressed))) {
        first start;
        then if (not alarmLocked) {
          first start;
          then assign count := (if ((count) == (0)) ? 15 else count - 1);
        }
      }
      then assign prevD2Pressed := io_0;
      then assign prevD3Pressed := io_1;
    }
    out attribute io_2 : Boolean = n == 2 * RealFunctions::floor(n / 2);
    out attribute io_3 : Integer = (if alarmLocked ? 440 else 0);
    out attribute io_4 : Integer = count;
  }
  part system : Controller;
}

